[System.IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant() -ne '6798b690daeea75cffd1ef4b9c0cbaab06036386b07b1db6c6e414dbff77a39b') { throw 'Pacote incorreto. Nada foi aplicado.' }
$pasta = Join-Path $PastaDestino ('Central-IPTV-atualizada-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
Expand-Archive -LiteralPath $zip -DestinationPath $pasta
$manifest = Get-Content -LiteralPath (Join-Path $pasta 'manifest.json') -Raw -Encoding UTF8 | ConvertFrom-Json
foreach ($entry in $manifest) {
    $arquivo = Join-Path $pasta $entry.file
    if ((Get-FileHash -LiteralPath $arquivo -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256) { throw ('Falha na verificacao de ' + $entry.file) }
}
Write-Host ('Pasta preparada: ' + $pasta)
Write-Host 'Site, Worker, wrangler.jsonc e package.json preparados e verificados.'
Write-Host 'Nenhum arquivo antigo foi substituido. Nada foi publicado. Banco e segredos nao foram alterados.'
Write-Host 'Envie o caminho desta pasta para continuarmos com a conferencia e a publicacao.'
